const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={brand:'Stüssy',product:'Graphic T-shirt',audience:'18–25-year-olds into streetwear, music and skate culture',goal:'Create interest',platform:'TikTok + Instagram Reels',tone:'Raw & understated',constraints:'Phone camera, two friends, local streets. No paid production.',notes:''};
let state={brief:{...defaults},selected:null,caption:'',entries:[],generated:false},step=0;try{const saved=JSON.parse(localStorage.getItem('creative-studio-v1'));if(saved&&saved.brief&&Array.isArray(saved.entries))state={...state,...saved}}catch{}
function save(){try{localStorage.setItem('creative-studio-v1',JSON.stringify(state))}catch{toast('Browser storage unavailable. Download your work to keep it.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function field(k,label,type='input',options=[]){const val=esc(state.brief[k]);return `<label class="${['audience','constraints'].includes(k)?'wide':''}">${label}${type==='select'?`<select name="${k}">${options.map(o=>`<option ${o===state.brief[k]?'selected':''}>${esc(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${k}" maxlength="1200">${val}</textarea>`:`<input name="${k}" value="${val}" required maxlength="180">`}</label>`}
function concepts(){const b=state.brief;return [{title:'Off the clock',hook:'The best part of the day has no schedule.',angle:`Follow a friend from a quiet doorway into the city. Let the ${b.product} become part of a real moment, rather than a product pose.`,trade:'Natural and easy to shoot; the product may need a closer shot to stay visible.',shots:['A static doorway shot. Your friend steps into frame.','Cut to the fabric and print in natural light.','Track a walk, a meet-up and a spontaneous laugh.','Hold on the product, then cut to a simple brand end card.']},{title:'One tee. Three lives.',hook:'Same piece. Different energy.',angle:`Three ways of wearing the ${b.product}, cut together through matching movements. Let each friend bring a different personality.`,trade:'Clear styling variety; needs consistent framing and more outfit preparation.',shots:['Close-up of the product thrown towards the camera.','Match cut to the first look walking into frame.','Repeat the movement for two more styling variations.','Show all looks in a quick triptych, then the end card.']},{title:'Look closer',hook:'You almost missed it.',angle:`Build a tactile portrait of the ${b.product}: texture, print and movement. Pair details with the sounds of the street.`,trade:'Can be shot solo; small details need steady focus and good daylight.',shots:['An extreme close-up of fabric with ambient street sound.','Pull focus to the print, then cut to a sleeve in motion.','Reveal the full look in a wide street shot.','Return to the first detail to make the video loop.']}];}
function captionDefault(){const c=concepts()[state.selected],b=state.brief;return `${c.hook}\n${b.brand} / ${b.product}.\n${b.goal==='Start a conversation'?'Which direction would you wear?':b.goal==='Show product details'?'Take a closer look.':'Save this for your next fit.'}`}
function go(n){step=n;render();document.querySelectorAll('nav button').forEach((b,i)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-current',i===n?'step':'false')})}
function render(){const p=$('#panel');if(step===0){p.innerHTML=`<div class="section-head"><div><h2>Start with a point of view.</h2><p class="sub">Make the brief yours. These are student project assumptions, not an official brand brief.</p></div><button class="secondary" id="reset">Load Stüssy example</button></div><div class="layout"><form id="brief"><div class="form-grid">${field('brand','BRAND')}${field('product','PRODUCT / FOCUS')}${field('audience','CAMPAIGN TARGET AUDIENCE')}${field('goal','CAMPAIGN GOAL','select',['Create interest','Show product details','Start a conversation'])}${field('platform','PLATFORM','select',['TikTok + Instagram Reels','TikTok','Instagram Reels'])}${field('tone','CREATIVE TONE','select',['Raw & understated','Playful & energetic','Quiet & cinematic'])}${field('constraints','PRODUCTION LIMITS','textarea')}</div><div class="actions"><button class="primary" type="submit">Explore three directions ↗</button><button class="secondary" type="button" id="prompt">Copy AI brief</button></div></form><aside class="aside"><p class="eyebrow">FOR CREATIVE INDUSTRY STUDENTS</p><h3>Your brief. Your perspective.</h3><p>Use the campaign lab for a creative project of your own. Stüssy is only an editable example, not the subject of the whole assistant.</p><span class="tag">PHONE-FIRST</span><span class="tag">15–20 SECONDS</span><span class="tag">YOUR DECISION</span><hr><p>The first module adapts three curated video campaign directions. Other creative workflows are planned. Copy your brief into an AI tool for an additional perspective, then record what you accept or reject.</p><p>Drafts save in this browser. Download your campaign for a portable copy.</p></aside></div>`;$('#brief').oninput=()=>{state.brief=Object.fromEntries(new FormData($('#brief')));save()};$('#brief').onsubmit=e=>{e.preventDefault();state.generated=true;state.selected=null;state.caption='';save();go(1)};$('#reset').onclick=()=>{if(confirm('Replace the current brief with the Stüssy example? Your decision journal will be kept.')){state.brief={...defaults};state.generated=false;state.selected=null;save();render()}};$('#prompt').onclick=()=>copy(promptText());return}
if(!state.generated){p.innerHTML='<div class="notice"><h2>Start with your brief.</h2><p>Set the product, audience and goal before exploring directions.</p><button class="primary" id="back">Go to the brief ↗</button></div>';$('#back').onclick=()=>go(0);return}
if(step===1){p.innerHTML=`<div class="section-head"><div><h2>Three ways into the story.</h2><p class="sub">${esc(state.brief.brand)} / ${esc(state.brief.product)} · Choose the idea you want to make.</p></div></div><div class="cards">${concepts().map((c,i)=>`<article class="card ${state.selected===i?'selected':''}"><span class="num">0${i+1}</span><h3>${c.title}</h3><p>${esc(c.angle)}</p><small><b>The trade-off</b><br>${c.trade}</small><button class="${state.selected===i?'primary':'secondary'}" data-choice="${i}">${state.selected===i?'Selected':'Develop this direction'} ↗</button></article>`).join('')}</div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.choice;state.caption=captionDefault();save();go(2)});return}
if(state.selected===null){p.innerHTML='<div class="notice"><h2>Choose your direction first.</h2><button class="primary" id="choose">See the concepts ↗</button></div>';$('#choose').onclick=()=>go(1);return}
const c=concepts()[state.selected],b=state.brief;
if(step===2){p.innerHTML=`<div class="section-head"><div><p class="eyebrow">SELECTED DIRECTION / 0${state.selected+1}</p><h2>${c.title}</h2><p class="sub">${esc(b.platform)} · 9:16 vertical · 15–20 seconds</p></div><button class="secondary" id="download">Download campaign ↓</button></div><div class="plan"><div><h3>THE SHOOT SEQUENCE</h3>${c.shots.map((s,i)=>`<div class="shot"><b>${['00–03s','03–07s','07–13s','13–18s'][i]}</b><span>${esc(s)}${i===0?`<br><small>On-screen text: “${c.hook}”</small>`:''}</span></div>`).join('')}<h3>CREATIVE NOTES</h3><p class="sub">${b.tone==='Quiet & cinematic'?'Hold shots longer and use restrained transitions.':b.tone==='Playful & energetic'?'Use quick match cuts and playful movement.':'Keep handheld movement and natural, unposed moments.'} Use original or licensed audio.</p><h3>YOUR PRODUCTION LIMITS</h3><p class="sub">${esc(b.constraints)}</p><h3>INTENDED AUDIENCE</h3><p class="sub">${esc(b.audience)}</p></div><aside><div class="caption"><p class="eyebrow">CAPTION / MAKE IT YOURS</p><label for="caption">Edit the draft</label><textarea id="caption" rows="6">${esc(state.caption)}</textarea><div class="actions"><button class="secondary" id="copyCaption" style="background:var(--lime)">Copy caption</button></div></div><div class="actions"><button class="primary" id="decide">Record my decisions ↗</button></div></aside></div>`;$('#caption').oninput=e=>{state.caption=e.target.value;save()};$('#copyCaption').onclick=()=>copy(state.caption);$('#download').onclick=download;$('#decide').onclick=()=>go(3);return}
p.innerHTML=`<div class="section-head"><div><h2>Your judgement is the point.</h2><p class="sub">Keep a real record of what you chose and why. Useful evidence for your PPB.</p></div><button class="secondary" id="download">Download campaign ↓</button></div><form id="decision"><div class="journal"><label>WHAT DID YOU KEEP, CHANGE OR REJECT?<textarea name="change" required maxlength="2000" placeholder="I chose this direction, but changed…"></textarea></label><label>WHY? WHAT WILL YOU TEST?<textarea name="reason" required maxlength="2000" placeholder="Because my audience… I want to test…"></textarea></label></div><div class="actions"><button class="primary">Save decision + date ↗</button></div></form><div>${state.entries.slice().reverse().map(e=>`<article class="entry"><time>${esc(e.date)} · ${esc(e.concept)} · ${esc(e.brand||'')}</time><p><b>My decision:</b> ${esc(e.change)}</p><p><b>My reason / next test:</b> ${esc(e.reason)}</p></article>`).join('')}</div>`;$('#decision').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));state.entries.push({...f,date:new Date().toLocaleString('en-GB'),concept:c.title,brand:b.brand});save();render();toast('Decision saved in this browser.')};$('#download').onclick=download;
}
function promptText(){return `Act as a creative campaign collaborator. This is independent student concept work, not an official brand campaign.\n${Object.entries(state.brief).map(([k,v])=>`${k}: ${v}`).join('\n')}\nPropose three distinct, feasible 15–20-second vertical video concepts. For each, explain the hook, audience fit, shot sequence, caption and production trade-offs. Respect the production limits. Mark assumptions and do not invent brand facts. Ask me to choose and critique a direction before developing it.`}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Copied.')}catch{toast('Clipboard unavailable. Use Download campaign to keep a copy.')}}
function download(){const c=concepts()[state.selected];const text=`CREATIVE STUDIO — STUDENT CAMPAIGN\nGenerated with curated templates; live AI not connected.\nIndependent work, not affiliated with ${state.brief.brand}.\n\nBRIEF\n${Object.entries(state.brief).map(([k,v])=>`${k}: ${v}`).join('\n')}\n\nDIRECTION: ${c?.title||'Not selected'}\n${c?.angle||''}\n\nSHOT PLAN\n${c?.shots.map((s,i)=>`${i+1}. ${s}`).join('\n')||''}\n\nCAPTION\n${state.caption}\n\nDECISION JOURNAL\n${state.entries.map(e=>`${e.date} | ${e.brand} | ${e.concept}\nDecision: ${e.change}\nReason: ${e.reason}`).join('\n\n')}\n\nAI BRIEF\n${promptText()}`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='creative-studio-campaign.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(+b.dataset.step));render();
